/** Llave natural de LA_PROGS[user, programa, copia, tipo]. */
public record LlavePrograma(int usuario, int programa, int copia, TipoPrograma tipo) {}

public enum TipoPrograma { PROGRAMA, LIBRERIA }   // DF_DP_TPGM_PROG = 1, DF_DP_TPGM_LIB = 2

/**
 * Sustituye LA_USERS, LA_PROGS, LA_DATOS_PROGS, LA_DATOS_ACT, LA_AGRUPXUSER y LA_PROGXAGRUP.
 * Los arreglos dispersos de MCP pasan a mapas: solo existen las llaves que se usan.
 */
@Component
public class RegistroProgramas {

    private final AtomicInteger siguienteIndice = new AtomicInteger(1);      // SIZE(LA_DATOS_PROGS) - 1
    private final ConcurrentMap<LlavePrograma, Integer> indices = new ConcurrentHashMap<>();
    private final ConcurrentMap<Integer, ProgramaEnCurso> programas = new ConcurrentHashMap<>();
    private final ConcurrentMap<Integer, ConcurrentMap<Integer, ProgramaEnCurso>> porAgrupador
            = new ConcurrentHashMap<>();                                    // LA_PROGXAGRUP

    /** LK_BEGINPROG: el alta es atómica por llave gracias a computeIfAbsent. */
    public int altaOIndice(LlavePrograma llave) {
        return indices.computeIfAbsent(llave, k -> siguienteIndice.getAndIncrement());
    }

    public Optional<ProgramaEnCurso> porIndice(int indice) {
        return Optional.ofNullable(programas.get(indice));
    }
}

/** Una fila de LA_DATOS_PROGS con sus 99 actividades de LA_DATOS_ACT. */
public final class ProgramaEnCurso {
    static final int MAX_ACTIVIDADES = 99;                                 // DF_NUM_ACTIV
    final ReentrantLock lock = new ReentrantLock();                        // en MCP no existe para actividades
    final ActividadEnCurso[] actividades = new ActividadEnCurso[MAX_ACTIVIDADES + 1];
    // usuario, programa, copia, tipo, nombre, fechas, mix, agrupador, estatus, procesoEnCurso...
}

/** Vistas tipadas de EA_ENTRADA / EA_SALIDA. Offsets y longitudes de los DEFINE IDF_ y DF_. */
public final class BufferMapli {

    public record InicioPrograma(int copia, int tipoDespliegue, int inicioGrupo,
                                 int numTipoProceso, String nomTipoProceso) {
        static final int LONGITUD_MINIMA = 48;
        static InicioPrograma de(byte[] b) {
            return new InicioPrograma(Ebcdic.entero(b, 0, 2), Ebcdic.entero(b, 2, 2),
                    Ebcdic.entero(b, 4, 2), Ebcdic.entero(b, 6, 2), Ebcdic.texto(b, 8, 40));
        }
    }

    public record InicioActividad(int idPrograma, long registrosAProcesar, int enActividad,
                                  int tipoActividad, int numActividad,
                                  String nombre, String textoAdicional) {
        static final int LONGITUD_MINIMA = 108;
        static InicioActividad de(byte[] b) {
            return new InicioActividad(Ebcdic.entero(b, 0, 8), Ebcdic.largo(b, 8, 10),
                    Ebcdic.entero(b, 18, 4), Ebcdic.entero(b, 22, 2), Ebcdic.entero(b, 24, 4),
                    Ebcdic.texto(b, 28, 40), Ebcdic.texto(b, 68, 40));
        }
    }

    public record FinActividad(int idPrograma, int numActividad) {}          // 12 bytes
    public record AvanceActividad(int idPrograma, int numActividad, String textoAdicional) {} // 52 bytes
}

/** Contrato que exportaba la librería: mismos nombres, mismos códigos de retorno. */
public interface MapliApi {
    ResultadoMapli inicioPrograma(LlavePrograma llave, InicioPrograma in, Consumer<Integer> idSalida); // _01
    ResultadoMapli finPrograma(int idPrograma);                                                    // _02
    ResultadoMapli inicioActividad(InicioActividad in, IntConsumer numActividadSalida);            // _03
    ResultadoMapli finActividad(FinActividad in);                                                  // _04
    ResultadoMapli avance(AvanceActividad in);                                                     // _05
    // _06 NUM_REGS, _30 USERXCSI, _31 AGRUPXUSER, _32 PROGSXAGRUP, _33 ACTIXPROG, _34 NUMDECSI
}

@Service
@RequiredArgsConstructor
public class MapliService implements MapliApi {

    private final RegistroProgramas registro;
    private final MapliRepository base;          // S500BD05MAPLI

    /** PROC_INICIO: abre la base, lee S038B01CONTROL y recarga el estado (CARGABASE). */
    @PostConstruct
    void inicio() {
        base.control().ifPresent(c -> registro.nodo(c.numNodo(), c.nomEquipo()));
        base.programasRegistrados().forEach(registro::restaura);
    }

    /** PROC_FIN tras FREEZE(TEMPORARY): el contenedor cierra el DataSource al apagarse. */
    @PreDestroy
    void fin() { log.info("MAPLI detenida"); }
}

public enum ResultadoMapli {
    OK(0), COPIA_FUERA_DE_RANGO(1), TIPO_PROGRAMA_INVALIDO(2), PROGRAMA_NO_DADO_DE_ALTA(3),
    ACTIVIDAD_FUERA_DE_RANGO(4), ACTIVIDAD_YA_EN_PROCESO(5), TIPO_ACTIVIDAD_INVALIDO(6),
    LIBRERIA_CON_REGISTROS(7), AVANCE_SOLO_PROCESO(8), NUM_PROGRAMA_FUERA_DE_RANGO(11),
    TIPO_PROCESO_FUERA_DE_RANGO(12), ACTIVIDAD_NO_EN_PROCESO(13), TIPO_DESPLIEGUE_INVALIDO(14),
    ACTIVIDAD_PADRE_INVALIDA(15), PROCESO_ANIDADO(16), FORMATO_INSUFICIENTE(17),
    INICIO_GRUPO_DISTINTO(18), PROGRAMA_NO_ACTIVO(19), FIN_PROGRAMA_NO_ACTIVO(20),
    LIBRERIA_NO_DISPONIBLE(99);
    public final int codigo;
    ResultadoMapli(int codigo) { this.codigo = codigo; }
}

/** VALIDA de S038L035_01_PROG_INI_C: la primera regla que falla determina el código. */
static ResultadoMapli valida(byte[] buffer, Identidad tarea, InicioPrograma in) {
    if (buffer.length < InicioPrograma.LONGITUD_MINIMA) return FORMATO_INSUFICIENTE;
    int numPgm = tarea.numeroPrograma();          // caracteres 20-22 de MYSELF.NAME
    if (numPgm < 1 || numPgm > 999)              return NUM_PROGRAMA_FUERA_DE_RANGO;
    if (in.copia() < 1 || in.copia() > 15)       return COPIA_FUERA_DE_RANGO;
    if (tarea.tipo().isEmpty())                  return TIPO_PROGRAMA_INVALIDO;  // ni 'P' ni 'L'
    if (in.numTipoProceso() < 1 || in.numTipoProceso() > 10) return TIPO_PROCESO_FUERA_DE_RANGO;
    if (in.tipoDespliegue() != 1 && in.tipoDespliegue() != 2) return TIPO_DESPLIEGUE_INVALIDO;
    if (in.inicioGrupo() > 0 && in.inicioGrupo() != in.numTipoProceso()) return INICIO_GRUPO_DISTINTO;
    return OK;
}

@Override
public ResultadoMapli inicioPrograma(LlavePrograma llave, InicioPrograma in, Consumer<Integer> idSalida) {
    ResultadoMapli r = valida(/* ... */);
    if (r != ResultadoMapli.OK) return r;

    int indice = registro.altaOIndice(llave);                 // LA_PROGS[...] o SIZE(LA_DATOS_PROGS)
    ProgramaEnCurso p = registro.programaPara(indice, llave);  // RESIZE ... RETAIN
    p.lock.lock();
    try {
        p.tiempoAnterior = p.tiempoActual;                     // DF_DP_ET_ANTERIOR := DF_DP_ET_ACTUAL
        p.procesoEnCurso = false;                              // DF_DP_PI_NO_ENCURSO
        for (int i = 1; i <= ProgramaEnCurso.MAX_ACTIVIDADES; i++) {
            ActividadEnCurso a = p.actividad(i);
            if (a.estatus() != EstatusActividad.NUNCA_INICIADA) a.estatus(EstatusActividad.NO_INICIADA);
            a.reinicia();                                       // registros, llamados, fechas, texto
        }
        p.inicia(in, LocalDateTime.now(), ProcessHandle.current().pid());   // MYSELF.MIXNUMBER
    } finally {
        p.lock.unlock();                                       // UNLOCK(LK_BEGINPROG)
    }
    idSalida.accept(indice);                                   // DF_PI_ID_PROG_S, 8 dígitos
    return ResultadoMapli.OK;
}

@Override
public ResultadoMapli inicioActividad(InicioActividad in, IntConsumer numActividadSalida) {
    // El chequeo de longitud (17) ocurre en el adaptador al construir el record.
    ProgramaEnCurso p = registro.porIndice(in.idPrograma()).orElse(null);
    if (p == null)                                        return PROGRAMA_NO_DADO_DE_ALTA;   // 3
    if (in.numActividad() < 1 || in.numActividad() > 99)  return ACTIVIDAD_FUERA_DE_RANGO;   // 4
    p.lock.lock();
    try {
        ActividadEnCurso a = p.actividad(in.numActividad());
        if (a.estatus() == EstatusActividad.EN_PROCESO)  return ACTIVIDAD_YA_EN_PROCESO;     // 5
        TipoActividad tipo = TipoActividad.de(in.tipoActividad()).orElse(null);
        if (tipo == null)                                return TIPO_ACTIVIDAD_INVALIDO;     // 6
        if (tipo == TipoActividad.LIBRERIA && in.registrosAProcesar() > 0)
                                                         return LIBRERIA_CON_REGISTROS;      // 7
        if (tipo == TipoActividad.PROCESO && p.procesoEnCurso) return PROCESO_ANIDADO;       // 16
        if (tipo == TipoActividad.LIBRERIA && in.enActividad() > 0
                && (in.enActividad() > 99
                    || p.actividad(in.enActividad()).estatus() != EstatusActividad.EN_PROCESO))
                                                         return ACTIVIDAD_PADRE_INVALIDA;    // 15
        if (!p.activo())                                 return PROGRAMA_NO_ACTIVO;          // 19
        p.iniciaActividad(in, LocalDateTime.now());      // ACTIINI
    } finally {
        p.lock.unlock();
    }
    numActividadSalida.accept(in.numActividad());
    return ResultadoMapli.OK;
}

/** S038L035_05_ACTU_REG_C: un llamado más y el texto adicional de la actividad. */
@Override
public ResultadoMapli avance(AvanceActividad in) {
    ProgramaEnCurso p = registro.porIndice(in.idPrograma()).orElse(null);
    if (p == null)                                        return PROGRAMA_NO_DADO_DE_ALTA;   // 3
    if (in.numActividad() < 1 || in.numActividad() > 99)  return ACTIVIDAD_FUERA_DE_RANGO;   // 4
    ActividadEnCurso a = p.actividad(in.numActividad());
    if (a.estatus() != EstatusActividad.EN_PROCESO)       return ACTIVIDAD_NO_EN_PROCESO;    // 13
    if (a.tipo() == TipoActividad.LIBRERIA)               return AVANCE_SOLO_PROCESO;        // 8

    a.llamados().incrementAndGet();                       // AtomicLong: no pierde incrementos
    a.textoAdicional(Ebcdic.ajusta(in.textoAdicional(), 42));
    return ResultadoMapli.OK;
}

/** Porcentaje de avance (I_PROC_PJEACT): llamados / registros a procesar * 100. */
int porcentaje(ActividadEnCurso a) {
    return switch (a.estatus()) {
        case NO_INICIADA -> 0;
        case EN_PROCESO -> a.registrosAProcesar() > 0
                ? (int) Math.round(a.llamados().get() * 100.0 / a.registrosAProcesar()) : 0;
        case TERMINADA -> 100;
        default -> 0;
    };
}

@Repository
@RequiredArgsConstructor
public class MapliRepository {

    private final ProgramaJpaRepository programas;      // S038B02PROGRAMAS, set B02SXIDPGM
    private final ActividadJpaRepository actividades;   // S038B03ACTIVIDAD, set B03SXIDACT

    /** GRABABASE: upsert del programa y de cada actividad usada, en una sola transacción. */
    @Transactional
    public void graba(ProgramaEnCurso p) {
        ProgramaEntity e = programas.findByLlaveForUpdate(p.llave())        // LOCK ... AT
                .orElseGet(() -> new ProgramaEntity(p.llave()));            // CREATE si NOTFOUND
        e.copiaDe(p);                                                       // PUT B02-...
        programas.save(e);                                                  // STORE

        for (ActividadEnCurso a : p.actividadesUsadas()) {
            if (a.estatus() == EstatusActividad.EN_PROCESO) {
                a.terminaCon(p.fechaFin(), p.horaFin());   // las que no terminaron se terminan
            }
            ActividadEntity ae = actividades.findByLlaveForUpdate(p.llave(), a.numero())
                    .orElseGet(() -> new ActividadEntity(p.llave(), a.numero()));
            ae.copiaDe(a);
            actividades.save(ae);
        }
        // Un error lanza excepción y revierte todo; el MCP seguía y confirmaba lo que hubiera.
    }
}

/** D_PROC_ET: microsegundos entre inicio y fin. Fechas AAAAMMDD, hora en microsegundos del día. */
public final class TiempoTranscurrido {

    public static long microsegundos(int fechaIni, long horaIniMicros, int fechaFin, long horaFinMicros) {
        LocalDateTime ini = LocalDate.parse(Integer.toString(fechaIni), DateTimeFormatter.BASIC_ISO_DATE)
                .atStartOfDay().plus(horaIniMicros, ChronoUnit.MICROS);
        LocalDateTime fin = LocalDate.parse(Integer.toString(fechaFin), DateTimeFormatter.BASIC_ISO_DATE)
                .atStartOfDay().plus(horaFinMicros, ChronoUnit.MICROS);
        return ChronoUnit.MICROS.between(ini, fin);   // cubre mismo día, mismo mes y cambio de mes o año
    }

    /** I_PROC_MMSTOHHMSCS: formato HHHHMMSSCC; los días se dejan en cero a propósito (nota 2 del fuente). */
    public static long aHhmmsscc(long micros) {
        Duration d = Duration.of(micros, ChronoUnit.MICROS);
        return d.toHours() * 1_000_000 + d.toMinutesPart() * 10_000
                + d.toSecondsPart() * 100L + d.toMillisPart() / 10;
    }
}
